"""Utility functions for parsing validation output from validation tools.

This module provides a centralized way to parse and interpret tool calls and outputs,
with a focus on the standardized validation output format. It provides both
general-purpose tool call extraction and specific validation parsing.

General tool call extraction:
- find_tool_calls(): Find all tool calls and their outputs
- find_last_tool_call(): Find the last call for a specific tool
- check_tool_called(): Check if a tool was called

Validation-specific parsing:
- parse_validation_block(): Parse validation format into structured data
- is_validation_successful(): Quick check for successful validation
- summarize_failure(): Generate concise failure summaries
- build_validation_output(): Create standardized validation output

The validation format consists of:
1. A validation summary with overall status:
   - ✅ VALID (fully valid)
   - ⚠️ VALID (with deprecated fields) - valid but with informational warnings
   - ❌ INVALID (failed)
2. Detailed results for each validation step, including:
   - Step name
   - Status (✅ SUCCESS, ⚠️ INFORM, or ❌ FAILED)
   - Optional detail message

Example validation output format:
    ## Validation Summary

    **Overall Status:** ❌ FAILED

    ## Detailed Results

    ### Input GraphQL and code compile

    **Status:** ❌ FAILED
    **Detail:** Compilation failed: error[E0433]: failed to resolve

This module makes it easy to:
- Extract validation blocks from tool output
- Parse the structured format into Python data structures
- Generate concise failure summaries
- Build new validation outputs in the correct format

Usage examples:
    # Extract all tool calls
    calls = find_tool_calls(text)
    for call in calls:
        print(f"{call.tool_name}: {call.output[:50]}...")

    # Find specific tool call
    graphql_result = find_last_tool_call(text, "validate_graphql_codeblocks")
    if graphql_result:
        print(graphql_result.output)

    # For GraphQL validation
    summary = summarize_failure(parsed, "GraphQL validation")
    # Output: "GraphQL validation failed: Step Name - error details"

    # For Liquid validation
    summary = summarize_failure(parsed, "Liquid validation")
    # Output: "Liquid validation failed: Step Name - error details"

    # For generic validation (default)
    summary = summarize_failure(parsed)
    # Output: "Validation failed: Step Name - error details"
"""

import re
from typing import Dict, List, Optional, Tuple, NamedTuple, Union, Any


class ToolCall(NamedTuple):
    """Represents a tool call and its output."""

    tool_name: str
    arguments: str
    output: str


def find_tool_calls(text: str, tool_name: Optional[str] = None) -> List[ToolCall]:
    """Find all tool calls and their outputs in the text.

    Args:
        text: The full text containing tool interactions
        tool_name: Optional specific tool name to filter for

    Returns:
        List of ToolCall objects containing tool calls and their outputs
    """
    # Pattern to match tool calls and their outputs
    # Captures: tool name, arguments, and the content between separators
    pattern = r"→ Called: ([^\s]+) with arguments:\s*([^\n]*)\n\n← Tool Output:\n-+\n(.*?)\n-+"

    outputs = []
    for match in re.finditer(pattern, text, re.DOTALL | re.MULTILINE):
        matched_tool_name = match.group(1)

        # Skip if filtering by tool name and it doesn't match
        if tool_name and matched_tool_name != tool_name:
            continue

        outputs.append(
            ToolCall(
                tool_name=matched_tool_name,
                arguments=match.group(2).strip(),
                output=match.group(3).strip(),
            )
        )

    return outputs


def find_last_tool_call(text: str, tool_name: str) -> Optional[ToolCall]:
    """Find the last call for a specific tool.

    Args:
        text: The full text containing tool interactions
        tool_name: The name of the tool to find

    Returns:
        The last ToolCall for the specified tool, or None if not found
    """
    calls = find_tool_calls(text, tool_name)
    return calls[-1] if calls else None


def parse_validation_block(block: str) -> Dict[str, any]:
    """Parse a validation block into structured data.

    Args:
        block: The validation block content (without the separators)

    Returns:
        A dictionary with:
        - overall_status: "VALID", "INFORM", or "FAILED"
        - steps: Dict mapping step names to {"status": "VALID"/"INFORM"/"FAILED", "detail": str}
    """
    result = {
        "overall_status": "FAILED",  # Default to failed
        "steps": {},
    }

    # Extract overall status - check for valid statuses (including with deprecated fields)
    # Match "✅ VALID" or "⚠️ VALID (with deprecated fields)"
    if re.search(r"\*\*Overall Status:\*\* ✅ VALID\b", block):
        result["overall_status"] = "VALID"
    elif re.search(r"\*\*Overall Status:\*\* ⚠️ VALID \(with deprecated fields\)", block):
        result["overall_status"] = "INFORM"
    elif re.search(r"\*\*Overall Status:\*\* ❌ (INVALID|FAILED)", block):
        result["overall_status"] = "FAILED"

    # Parse individual steps
    # Pattern to match step sections with their status and optional detail
    # Supports SUCCESS, INFORM, and FAILED statuses
    step_pattern = r"### ([^\n]+)\n\n\*\*Status:\*\* (✅ SUCCESS|⚠️ INFORM|❌ FAILED)(?:\n\*\*Details?:\*\* ([^\n]+))?"

    for match in re.finditer(step_pattern, block):
        step_name = match.group(1)
        status_str = match.group(2)
        if "✅ SUCCESS" in status_str:
            status = "VALID"
        elif "⚠️ INFORM" in status_str:
            status = "INFORM"
        else:
            status = "FAILED"
        detail = match.group(3).strip() if match.group(3) else ""

        result["steps"][step_name] = {"status": status, "detail": detail}

    return result


def summarize_failure(
    parsed: Dict[str, any], validation_type: str = "Validation"
) -> str:
    """Create a concise failure summary from parsed validation data.

    Args:
        parsed: The parsed validation data from parse_validation_block
        validation_type: Type of validation (e.g., "Function validation", "GraphQL validation")
                        Defaults to generic "Validation"

    Returns:
        A human-readable failure reason string
    """
    # Find the first failed step
    for step_name, step_info in parsed["steps"].items():
        if step_info["status"] == "FAILED":
            if step_info["detail"]:
                # Extract first error message if it's a compilation error
                error_match = re.search(
                    r"error\[E\d+\]: (.+?)(?:\n|$)", step_info["detail"]
                )
                if error_match:
                    return f"{validation_type} failed: {step_name} - {error_match.group(1)}"
                else:
                    return (
                        f"{validation_type} failed: {step_name} - {step_info['detail']}"
                    )
            else:
                return f"{validation_type} failed: {step_name}"

    # Fallback if no specific failed step found
    return f"{validation_type} failed"


def check_tool_called(output: str, tool_name: str) -> bool:
    """Check if a specific tool was called in the output.

    Args:
        output: The full output string
        tool_name: Name of the tool to check for

    Returns:
        True if the tool was called, False otherwise
    """
    return len(find_tool_calls(output, tool_name)) > 0


def is_validation_successful(output: str, tool_name: str) -> bool:
    """Quick check if validation was successful without full parsing.

    A validation is considered successful if:
    - Overall status is "✅ VALID" (fully valid)
    - Overall status is "⚠️ VALID (with deprecated fields)" (valid with informational warnings)

    Args:
        output: The full output string
        tool_name: Name of the validation tool

    Returns:
        True if validation passed (including INFORM status), False otherwise
    """
    tool_call = find_last_tool_call(output, tool_name)
    if not tool_call:
        return False

    # Check if the output contains successful validation pattern
    # Match both "✅ VALID" and "⚠️ VALID (with deprecated fields)"
    success_pattern = r"## Validation Summary\n\n\*\*Overall Status:\*\* (✅ VALID|⚠️ VALID \(with deprecated fields\))"
    return bool(re.search(success_pattern, tool_call.output, re.MULTILINE))


def build_validation_output(
    overall_status: str, steps: List[Union[Tuple[str, str], Tuple[str, str, str]]]
) -> str:
    """Build a standardized validation output string.

    Args:
        overall_status: "VALID", "INFORM", or "FAILED"
        steps: List of tuples (step_name, status) or (step_name, status, detail)
               where status is "VALID", "INFORM", or "FAILED"
               detail is optional

    Returns:
        Formatted validation output string
    """
    # Determine overall status icon and text
    if overall_status == "VALID":
        overall_icon = "✅"
        overall_text = "VALID"
    elif overall_status == "INFORM":
        overall_icon = "⚠️"
        overall_text = "VALID (with deprecated fields)"
    else:
        overall_icon = "❌"
        overall_text = "INVALID"

    lines = [
        "## Validation Summary",
        "",
        f"**Overall Status:** {overall_icon} {overall_text}",
        "",
        "## Detailed Results",
        "",
    ]

    for step_tuple in steps:
        step_name, status = step_tuple[:2]
        detail = step_tuple[2] if len(step_tuple) > 2 else None

        # Determine step status icon
        if status == "VALID":
            step_icon = "✅"
            step_text = "SUCCESS"
        elif status == "INFORM":
            step_icon = "⚠️"
            step_text = "INFORM"
        else:
            step_icon = "❌"
            step_text = "FAILED"

        lines.append(f"### {step_name}")
        lines.append("")
        lines.append(f"**Status:** {step_icon} {step_text}")
        if detail:
            lines.append(f"**Details:** {detail}")
        lines.append("")

    return "\n".join(lines).rstrip()
